### Insert with onConflictDoUpdate (upsert)

Source: https://github.com/drizzle-team/drizzle-orm-docs/blob/main/src/content/docs/pg/insert.mdx

Shows `.onConflictDoUpdate()` on inserts to update the conflicting row, including the composite-index/composite-primary-key variant that targets an array of columns, directly answering the inserts onConflictDoUpdate part of the query.

```typescript
await db.insert(users)
  .values({ id: 1, name: 'Dan' })
  .onConflictDoUpdate({ target: users.id, set: { name: 'John' } });

await db.insert(users)
  .values({ firstName: 'John', lastName: 'Doe' })
  .onConflictDoUpdate({
    target: [users.firstName, users.lastName],
    set: { firstName: 'John1' }
  });
```

--------------------------------

### Define UNIQUE constraints

Source: https://github.com/drizzle-team/drizzle-orm-docs/blob/main/src/content/docs/pg/indexes-constraints.mdx

Enforces column or composite column uniqueness, custom constraint names, and PostgreSQL 15+ NULLS NOT DISTINCT options.

```typescript
import { integer, text, unique, pgTable } from "drizzle-orm/pg-core";

export const user = pgTable('user', {
  id: integer().unique(),
});

export const table = pgTable('table', {
  id: integer().unique('custom_name'),
});

export const composite = pgTable('composite_example', {
  id: integer(),
  name: text(),
}, (t) => [
  unique().on(t.id, t.name),
  unique('custom_name').on(t.id, t.name)
]);

// In Postgres 15.0+ NULLS NOT DISTINCT is available
// This example demonstrates both available usages
export const userNulls = pgTable("user_nulls_example", {
	id: integer(),
	id2: integer().unique("custom_name", { nulls: "not distinct" }),
}, (t) => [
	unique().on(t.id).nullsNotDistinct()
]);
```

```sql
CREATE TABLE "user" (
	"id" integer UNIQUE
);

CREATE TABLE "table" (
	"id" integer CONSTRAINT "custom_name" UNIQUE
);

CREATE TABLE "composite_example" (
	"id" integer,
	"name" text,
	CONSTRAINT "composite_example_id_name_unique" UNIQUE("id","name"),
	CONSTRAINT "custom_name" UNIQUE("id","name")
);

CREATE TABLE "user_nulls_example" (
	"id" integer UNIQUE NULLS NOT DISTINCT,
	"id2" integer CONSTRAINT "custom_name" UNIQUE NULLS NOT DISTINCT
);
```

--------------------------------

### Upsert single row using onConflictDoUpdate

Source: https://github.com/drizzle-team/drizzle-orm-docs/blob/main/src/content/docs/guides/upsert.mdx

Performs an upsert query targeting a column conflict in PostgreSQL, CockroachDB, and SQLite.

```typescript
import { users } from './schema';

const db = drizzle(...);

await db
  .insert(users)
  .values({ id: 1, name: 'John' })
  .onConflictDoUpdate({
    target: users.id,
    set: { name: 'Super John' },
  });
```

```sql
insert into users ("id", "name") values (1, 'John')
  on conflict ("id") do update set name = 'Super John';
```

--------------------------------

### Define PostgreSQL unique constraints with pgTable

Source: https://github.com/drizzle-team/drizzle-orm-docs/blob/main/src/content/docs/latest-releases/drizzle-orm-v0272.mdx

Demonstrates single-column and multi-column unique constraints in PostgreSQL schemas using pgTable. Supports custom constraint names and the nullsNotDistinct() / { nulls: 'not distinct' } option.

```typescript
// single column
const table = pgTable('table', {
  id: serial('id').primaryKey(),
  name: text('name').notNull().unique(),
  state: char('state', { length: 2 }).unique('custom'),
  field: char('field', { length: 2 }).unique('custom_field', { nulls: 'not distinct' }),
});
// multiple columns
const table = pgTable('table', {
  id: serial('id').primaryKey(),
  name: text('name').notNull(),
  state: char('state', { length: 2 }),
}, (t) => ({
  first: unique('custom_name').on(t.name, t.state).nullsNotDistinct(),
  second: unique('custom_name1').on(t.name, t.state),
}));
```

--------------------------------

### Use postgres.js driver with Drizzle ORM

Source: https://github.com/drizzle-team/drizzle-orm-docs/blob/main/src/content/docs/latest-releases/drizzle-orm-v0162.mdx

Defines a PostgreSQL schema and initializes a database connection using the postgres.js driver integration.

```typescript
// schema.ts
import { pgTable, serial, text, varchar } from "drizzle-orm-pg";
export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  fullName: text("full_name"),
  phone: varchar("phone", { length: 256 }),
});

// index.ts
import { drizzle, PostgresJsDatabase } from "drizzle-orm-pg/postgres.js";
import postgres from "postgres";
import { users } from "./schema";

const client = postgres(connectionString);
const db: PostgresJsDatabase = drizzle(client);

const allUsers = await db.select(users);
```

